/**
 * Weight configuration for search result scoring
 */
export type SearchWeights = {
  /**
   * Weight for fuzzy match results
   * @default 0.45
   */
  fuzzy?: number
  /**
   * Weight for prefix match results
   * @default 0.375
   */
  prefix?: number
}

// In SearchOptions:
weights?: SearchWeights

