// Helper function (add near top of class or in utils):
private resolveSearchWeights(weights?: SearchWeights): Required<SearchWeights> {
  return {
    fuzzy: weights?.fuzzy ?? defaultSearchOptions.weights.fuzzy,
    prefix: weights?.prefix ?? defaultSearchOptions.weights.prefix
  };
}

// Usage:
const { fuzzy: fuzzyWeight, prefix: prefixWeight } = this.resolveSearchWeights(weights);

